targets.expr:
sum by (interface, mac_address, address, dynamic, status) (
    sort_by_label(
        mtik_exporter_arp_entry_info{routerboard_name="$node", dhcp_lease_type!="static"},
        "interface"
    )
)

sum by (mac_address, interface, ssid, active_address, comment) (
    mtik_exporter_wifi_clients_devices_info{routerboard_name="$node"} * on (mac_address) group_left(comment, active_address) mtik_exporter_dhcp_lease_info{routerboard_name="$node"} or on (mac_address) mtik_exporter_wifi_clients_devices_info{routerboard_name="$node"}
)

sum by (address, comment, active_address, address, interface, mac_address, mac_vendor, router, status) (
    last_over_time(
        mtik_exporter_ipv6_neighbor_info{routerboard_name="$node"}[1h]
    ) * on (mac_address) group_left(comment, active_address)
        mtik_exporter_dhcp_lease_info{routerboard_name="$node"}

    or on (mac_address)
    last_over_time(
        mtik_exporter_ipv6_neighbor_info{routerboard_name="$node"}[1h]
    )
)
